cd /home/xy/.qoder-cn && /usr/bin/python3 -c "
import json,re
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): yield from walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o[:20]): yield from walk(v,p+f'[{i}]')
    else:
        yield p,o
for path in ('state.json','umid-cache.json'):
    try: raw=open(path,encoding='utf-8').read()
    except Exception as e: print(path,'读取失败',e); continue
    try: data=json.loads(raw)
    except Exception as e: print(path,'非 JSON',e); continue
    print('===',path,'===')
    for p,v in walk(data):
        if re.search(r'uid|user|account|email|nick|login',p,re.I):
            s=str(v)
            print(' ',p,'=',s if len(s)<=64 else s[:20]+'…(长度 %d，已省略)'%len(s))
"
